before.auth/session.mjs:
export function sessionFor(user, session, now) {
  if (!session) return null;
  return session;
}

before.auth/token.mjs:
import { allowUnsigned } from '../config/token-policy.mjs';
export function acceptToken(token) {
  return token.signed || allowUnsigned;
}

after.auth/session.mjs:
export function sessionFor(user, session, now) {
  if (!session) return null;
  if (session.tenantId !== user.tenantId) return null;
  return session;
}

after.auth/token.mjs:
import { allowUnsigned } from '../config/token-policy.mjs';
export function acceptToken(token) {
  return token.signed || allowUnsigned;
}
